INSERT INTO `v1_b0098477468fb655b7130dacc54f4b4dd3c80f0c3247b86802be6efa54a7c73d` VALUES ("boss_tp_down_cut", "バトル開始時、すべてのモンスターがＴＰダウン\n75％カット状態になる。", 4100710, "ＴＰダウンカット", 10071005);
INSERT INTO `v1_b0098477468fb655b7130dacc54f4b4dd3c80f0c3247b86802be6efa54a7c73d` VALUES (3, "バトル開始時、すべてのキャラのＴＰ上昇をダウンさせる。", 4100710, "ＴＰ上昇ダウン", 10071006);
INSERT INTO `v1_b0098477468fb655b7130dacc54f4b4dd3c80f0c3247b86802be6efa54a7c73d` VALUES (9, "バトル開始時、すべてのキャラのＨＰ吸収をダウンさせる。", 4100710, "ＨＰ吸収ダウン", 10071007);
